const i = $('Entrada').first().json;
const DUE_LANG = ($env.CHRONOS_LOCALE || 'pt-BR').split('-')[0]; // idioma dos prazos no Todoist, da locale do .env (pt-BR → pt)
let subs = [];
try { subs = JSON.parse(i.subs_json || '[]'); } catch (e) { subs = []; }
if (!i.parent_id || !Array.isArray(subs) || !subs.length) return [{ json: { skip: true } }];
return subs.map((s) => ({ json: { skip: false, title: s.title, body: { content: s.title, parent_id: String(i.parent_id), priority: Number(i.priority) || 1, due_lang: DUE_LANG, ...(s.due ? { due_string: s.due } : {}) } } }));

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const prep = $('Preparar subtarefas').all().map((i) => i.json);
if (!prep.length || prep[0].skip) return [{ json: { total: 0, created: 0, failed: 0, lines: '' } }];
const res = $input.all().map((i) => i.json);
const ok = [];
const bad = [];
prep.forEach((p, i) => {
  const r = res[i] || {};
  if (r.id) ok.push(p.title);
  else {
    const raw = String((r.error && (r.error.message || r.error)) || r.message || 'erro desconhecido');
    const code = raw.match(/^\s*(\d{3})\b/);
    bad.push({ title: p.title, why: code ? 'erro ' + code[1] + ' do Todoist' : raw.slice(0, 80) });
  }
});
const lines = [];
if (ok.length) lines.push('↳ ' + ok.length + (ok.length === 1 ? ' subtarefa: ' : ' subtarefas: ') + ok.slice(0, 5).map(esc).join(' · ') + (ok.length > 5 ? ' · +' + (ok.length - 5) : ''));
if (bad.length) lines.push('⚠️ ' + bad.length + ' de ' + prep.length + (bad.length === 1 ? ' subtarefa não foi criada: ' : ' subtarefas não foram criadas: ') + bad.slice(0, 5).map((b) => esc(b.title)).join(', ') + ' <i>(' + esc(bad[0].why) + ')</i>');
return [{ json: { total: prep.length, created: ok.length, failed: bad.length, lines: lines.join('\n') } }];
